<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { consultarComprobantes, obtenerDocumentosComprobante, obtenerOpcionesComprobantes } from '../services/comprobantesProceso'
import type { ComprobanteProceso, FiltrosComprobantesProceso, TipoComprobanteProceso } from '../interfaces/comprobantesProceso.interface'
const filtros=reactive<FiltrosComprobantesProceso>({fecha_desde:'',fecha_hasta:'',tipo_comprobante_id:null,tipo_documento_id:null,nro_desde:'',nro_hasta:''}),tipos=ref<TipoComprobanteProceso[]>([]),documentos=ref<TipoComprobanteProceso[]>([]),rows=ref<ComprobanteProceso[]>([]),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function load(){loading.value=true;try{const r=await obtenerOpcionesComprobantes();tipos.value=r.tipos_comprobante;documentos.value=r.tipos_documento??[];rows.value=r.data??[]}catch(v){error.value=message(v)}finally{loading.value=false}}
async function changeType(){filtros.tipo_documento_id=null;documentos.value=filtros.tipo_comprobante_id?await obtenerDocumentosComprobante(filtros.tipo_comprobante_id):[]}
async function search(){if(!filtros.fecha_desde||!filtros.fecha_hasta)return void(error.value='Seleccione el rango de fechas.');if(filtros.fecha_desde>filtros.fecha_hasta)return void(error.value='La fecha inicial no puede ser mayor que la fecha final.');loading.value=true;consultado.value=true;error.value='';try{const r=await consultarComprobantes(filtros);rows.value=r.data}catch(v){error.value=message(v)}finally{loading.value=false}}
function clear(){Object.assign(filtros,{fecha_desde:'',fecha_hasta:'',tipo_comprobante_id:null,tipo_documento_id:null,nro_desde:'',nro_hasta:''});documentos.value=[];rows.value=[];consultado.value=false;error.value=''}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Comprobantes</nav><header class="hero"><div class="mark">CP</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Comprobantes contables</h1><p>Consulta comprobantes registrados y revisa su asiento contable detallado.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Fecha desde *<input v-model="filtros.fecha_desde" type="date"></label><label>Fecha hasta *<input v-model="filtros.fecha_hasta" type="date"></label><label>Tipo comprobante<select v-model="filtros.tipo_comprobante_id" @change="changeType"><option :value="null">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Tipo documento<select v-model="filtros.tipo_documento_id"><option :value="null">Todos</option><option v-for="o in documentos" :key="o.id" :value="o.id">{{o.nombre}} {{o.diminutivo?`(${o.diminutivo})`:''}}</option></select></label><label>N.° desde<input v-model.trim="filtros.nro_desde" placeholder="000001"></label><label>N.° hasta<input v-model.trim="filtros.nro_hasta" placeholder="000010"></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Consultando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Consultando comprobantes…</div><div v-else-if="consultado&&!rows.length" class="empty">No se encontraron comprobantes con los filtros seleccionados.</div><div v-else-if="!consultado" class="empty">Seleccione un rango de fechas para visualizar los comprobantes.</div><main v-else><article v-for="comp in rows" :key="comp.id??`${comp.numero}-${comp.fecha_contable}`" class="voucher"><header><b>Comprobante #{{comp.numero}}</b><span>{{comp.tipo_comprobante}}</span></header><section class="info"><div><b>Responsable</b><span>{{comp.responsable}}</span><b>Origen</b><span>{{comp.origen}}</span><b>Fecha contable</b><span>{{comp.fecha_contable}}</span></div><div><b>Documento</b><span>{{comp.documento}}</span><b>Fecha documento</b><span>{{comp.fecha_doc||'—'}}</span><b>Moneda</b><span>{{comp.moneda}}</span></div></section><p v-if="comp.glosa" class="glosa"><b>Glosa:</b> {{comp.glosa}}</p><div class="scroll"><table><thead><tr><th>Cuenta</th><th>Nombre de la cuenta</th><th>Debe S/</th><th>Haber S/</th><th>C. costos / Analítico</th></tr></thead><tbody><tr v-for="(det,i) in comp.detalles" :key="`${comp.numero}-${i}`"><td><b>{{det.cta_contable}}</b></td><td>{{det.descripcion_cuenta}}</td><td class="num">{{money(det.debe)}}</td><td class="num">{{money(det.haber)}}</td><td>{{det.cc_analitico||'—'}}</td></tr></tbody><tfoot><tr><th colspan="2">Total</th><td class="num">{{money(comp.total_debe)}}</td><td class="num">{{money(comp.total_haber)}}</td><td></td></tr></tfoot></table></div></article></main></div></template>
<style scoped>
.page{--a:#426f9f;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.flash{padding:9px;color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:15px;display:grid;grid-template-columns:repeat(6,1fr);gap:8px;background:#fff}.filters label{display:grid;gap:5px;font-size:.49rem}.filters input,.filters select{min-width:0;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.52rem}.filters footer{grid-column:1/-1;display:flex;justify-content:flex-end;gap:6px}.filters button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff}.voucher{margin-top:16px;border-radius:9px;background:#fff;overflow:hidden}.voucher>header{padding:10px 14px;display:flex;justify-content:space-between;color:#fff;background:#334b58;font-size:.6rem}.voucher>header span{padding:3px 7px;border-radius:10px;color:#334b58;background:#fff;font-size:.46rem}.info{padding:12px 14px;display:grid;grid-template-columns:1fr 1fr;gap:20px}.info div{display:grid;grid-template-columns:105px 1fr;gap:5px;font-size:.5rem}.info b{color:#66747b}.glosa{margin:0 14px 10px;font-size:.52rem}.scroll{overflow:auto}table{width:100%;min-width:760px;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{background:#edf1f3}tfoot{background:#dfe5e8}.num{text-align:right;font-family:monospace}@media(max-width:900px){.filters{grid-template-columns:repeat(3,1fr)}}@media(max-width:580px){.filters,.info{grid-template-columns:1fr}.info div{grid-template-columns:90px 1fr}}
</style>
